<div class="panel narrow-panel"><div class="panel-heading"><div><h2>General configuration</h2><p>Application settings stored in the database.</p></div></div><form method="post" action="/admin/settings/save" class="form-stack"><input type="hidden" name="_csrf" value="<?= esc(\Brightery\Core\App::get()->service(\Brightery\Core\Security::class)->csrf()) ?>"><label class="bf-field"><span>Site name</span><input name="site_name" maxlength="150" value="<?= esc($settings['site_name']??'Brightery Framework') ?>"></label><label class="bf-field"><span>Support email</span><input name="support_email" type="email" value="<?= esc($settings['support_email']??'') ?>"></label><label class="bf-field"><span>Site description</span><textarea name="site_description" rows="5" maxlength="500"><?= esc($settings['site_description']??'') ?></textarea></label><button class="btn btn-primary" type="submit">Save settings →</button></form><div class="hint">Secrets, database access and other infrastructure configuration belong in the private <code>.env</code> file—not in an administrative form.</div></div>
